#include <Arduino.h>
#include <WiFi.h>
#include <SPI.h>
#include <U8g2lib.h>

// ==========================================
// OLED: ТВОЯ ПРЕЖНЯЯ РАСПИНОВКА SPI
// CLK  -> GPIO 18
// MOSI -> GPIO 23
// CS   -> GPIO 5
// DC   -> GPIO 17
// RST  -> GPIO 16
// ==========================================

U8G2_SSD1306_128X64_NONAME_F_4W_HW_SPI oled(
  U8G2_R0, 5, 17, 16
  );

  // Единственная кнопка
  // Один контакт -> GPIO 4 (D4)
  // Второй контакт -> GND
  const uint8_t BUTTON_PIN = 4;

  // Настройки управления
  const uint16_t DEBOUNCE_MS = 25;
  const uint16_t LONG_PRESS_MS = 750;
  const uint16_t CLICK_GAP_MS = 380;

  // Параметры Wi-Fi
  const uint8_t MAX_NETWORKS = 32;
  const uint32_t AUTO_SCAN_MS = 25000;
  const uint32_t FULL_SCAN_TIMEOUT_MS = 18000;
  const uint32_t TRACK_SCAN_TIMEOUT_MS = 5000;

  // Для измерения выбранной сети сканируется
  // только её канал. Это быстрее полного сканирования.
  const uint16_t CHANNEL_SCAN_MS = 120;
  const uint16_t TRACK_RETRY_DELAY_MS = 40;

  // История сигнала
  const uint8_t HISTORY_SIZE = 64;

  // ==========================================
  // СТРУКТУРЫ И РЕЖИМЫ
  // ==========================================

  struct NetworkInfo {
    char ssid[33];
      char bssid[18];
        int32_t rssi;
          int32_t channel;
            bool open;
            };

            NetworkInfo networks[MAX_NETWORKS];

            enum ScreenMode {
              LIST_SCREEN,
                SIGNAL_SCREEN
                };

                enum ScanKind {
                  NO_SCAN,
                    FULL_SCAN,
                      TRACK_SCAN
                      };

                      ScreenMode screenMode = LIST_SCREEN;
                      ScanKind scanKind = NO_SCAN;

                      int networkCount = 0;
                      int totalFound = 0;
                      int selectedIndex = 0;

                      bool scanning = false;
                      bool scanError = false;

                      unsigned long scanStartedAt = 0;
                      unsigned long lastFullScanAt = 0;
                      unsigned long nextTrackScanAt = 0;
                      unsigned long lastDrawAt = 0;

                      // Кнопка и определение комбинаций
                      uint8_t buttonLastReading = HIGH;
                      uint8_t buttonStableLevel = HIGH;

                      unsigned long lastDebounceAt = 0;
                      unsigned long buttonPressedAt = 0;
                      unsigned long lastClickAt = 0;

                      bool longActionDone = false;
                      uint8_t pendingClicks = 0;

                      // Измеритель сигнала
                      int32_t currentRSSI = -100;
                      uint8_t missedSamples = 0;

                      int16_t history[HISTORY_SIZE];
                      uint8_t historyHead = 0;

                      // ==========================================
                      // ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
                      // ==========================================

                      void startFullScan();
                      void startTrackScan();
                      void drawScreen();
                      void handleScanResults(int16_t found);
                      void handleScanFailure();

                      void pushHistory(int32_t rssi) {
                        if (rssi < -100) rssi = -100;
                          if (rssi > -20) rssi = -20;

                            history[historyHead] = rssi;
                              historyHead = (historyHead + 1) % HISTORY_SIZE;
                              }

                              void resetHistory(int32_t rssi) {
                                if (rssi < -100) rssi = -100;
                                  if (rssi > -20) rssi = -20;

                                    for (uint8_t i = 0; i < HISTORY_SIZE; i++) {
                                        history[i] = rssi;
                                          }

                                            historyHead = 0;
                                            }

                                            void trimText(char *text, uint8_t maxWidth) {
                                              if (oled.getUTF8Width(text) <= maxWidth) return;

                                                size_t len = strlen(text);

                                                  while (len > 0) {
                                                      len--;

                                                          // Не разрезаем UTF-8 символ посередине
                                                              while (len > 0 &&
                                                                         (static_cast<uint8_t>(text[len]) & 0xC0) == 0x80) {
                                                                               len--;
                                                                                   }

                                                                                       text[len] = '\0';

                                                                                           if (oled.getUTF8Width(text) +
                                                                                                   oled.getStrWidth("~") <= maxWidth) {
                                                                                                         strcat(text, "~");
                                                                                                               return;
                                                                                                                   }
                                                                                                                     }
                                                                                                                     }

                                                                                                                     void sortNetworks() {
                                                                                                                       for (int i = 0; i < networkCount - 1; i++) {
                                                                                                                           for (int j = i + 1; j < networkCount; j++) {
                                                                                                                                 if (networks[j].rssi > networks[i].rssi) {
                                                                                                                                         NetworkInfo temp = networks[i];
                                                                                                                                                 networks[i] = networks[j];
                                                                                                                                                         networks[j] = temp;
                                                                                                                                                               }
                                                                                                                                                                   }
                                                                                                                                                                     }
                                                                                                                                                                     }

                                                                                                                                                                     void moveSelection(uint8_t amount) {
                                                                                                                                                                       if (networkCount <= 0) return;

                                                                                                                                                                         selectedIndex =
                                                                                                                                                                             (selectedIndex + amount) % networkCount;
                                                                                                                                                                             }

                                                                                                                                                                             void toggleSignalScreen() {
                                                                                                                                                                               if (screenMode == LIST_SCREEN) {
                                                                                                                                                                                   if (networkCount <= 0) {
                                                                                                                                                                                         startFullScan();
                                                                                                                                                                                               return;
                                                                                                                                                                                                   }

                                                                                                                                                                                                       screenMode = SIGNAL_SCREEN;

                                                                                                                                                                                                           currentRSSI = networks[selectedIndex].rssi;
                                                                                                                                                                                                               missedSamples = 0;
                                                                                                                                                                                                                   resetHistory(currentRSSI);

                                                                                                                                                                                                                       nextTrackScanAt = millis();

                                                                                                                                                                                                                           Serial.printf(
                                                                                                                                                                                                                                 "Signal monitor: %s, channel %ld, BSSID %s\n",
                                                                                                                                                                                                                                       networks[selectedIndex].ssid,
                                                                                                                                                                                                                                             (long)networks[selectedIndex].channel,
                                                                                                                                                                                                                                                   networks[selectedIndex].bssid
                                                                                                                                                                                                                                                       );
                                                                                                                                                                                                                                                         } else {
                                                                                                                                                                                                                                                             screenMode = LIST_SCREEN;

                                                                                                                                                                                                                                                                 Serial.println("Returned to Wi-Fi list");
                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                   // ==========================================
                                                                                                                                                                                                                                                                   // ОБРАБОТКА КНОПКИ
                                                                                                                                                                                                                                                                   // ==========================================

                                                                                                                                                                                                                                                                   void processPendingClicks() {
                                                                                                                                                                                                                                                                     uint8_t count = pendingClicks;
                                                                                                                                                                                                                                                                       pendingClicks = 0;

                                                                                                                                                                                                                                                                         // Обычные нажатия работают в списке.
                                                                                                                                                                                                                                                                           // В режиме измерения сеть остаётся выбранной.
                                                                                                                                                                                                                                                                             if (screenMode == LIST_SCREEN && count > 0) {
                                                                                                                                                                                                                                                                                 moveSelection(count);
                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                   void registerShortClick(unsigned long now) {
                                                                                                                                                                                                                                                                                     if (pendingClicks > 0 &&
                                                                                                                                                                                                                                                                                           now - lastClickAt > CLICK_GAP_MS) {
                                                                                                                                                                                                                                                                                               processPendingClicks();
                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                   pendingClicks++;
                                                                                                                                                                                                                                                                                                     lastClickAt = now;

                                                                                                                                                                                                                                                                                                       // Три быстрых нажатия открывают/закрывают измеритель.
                                                                                                                                                                                                                                                                                                         if (pendingClicks >= 3) {
                                                                                                                                                                                                                                                                                                             pendingClicks = 0;
                                                                                                                                                                                                                                                                                                                 toggleSignalScreen();
                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                   void handleLongPress() {
                                                                                                                                                                                                                                                                                                                     pendingClicks = 0;

                                                                                                                                                                                                                                                                                                                       if (screenMode == LIST_SCREEN) {
                                                                                                                                                                                                                                                                                                                           startFullScan();
                                                                                                                                                                                                                                                                                                                             } else {
                                                                                                                                                                                                                                                                                                                                 // Обнуляем историю, но продолжаем наблюдать за сетью.
                                                                                                                                                                                                                                                                                                                                     resetHistory(currentRSSI);
                                                                                                                                                                                                                                                                                                                                         missedSamples = 0;

                                                                                                                                                                                                                                                                                                                                             Serial.println("Signal graph cleared");
                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                               void updateButton() {
                                                                                                                                                                                                                                                                                                                                                 unsigned long now = millis();
                                                                                                                                                                                                                                                                                                                                                   uint8_t reading = digitalRead(BUTTON_PIN);

                                                                                                                                                                                                                                                                                                                                                     if (reading != buttonLastReading) {
                                                                                                                                                                                                                                                                                                                                                         buttonLastReading = reading;
                                                                                                                                                                                                                                                                                                                                                             lastDebounceAt = now;
                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                 if (now - lastDebounceAt >= DEBOUNCE_MS &&
                                                                                                                                                                                                                                                                                                                                                                       reading != buttonStableLevel) {

                                                                                                                                                                                                                                                                                                                                                                           buttonStableLevel = reading;

                                                                                                                                                                                                                                                                                                                                                                               if (buttonStableLevel == LOW) {
                                                                                                                                                                                                                                                                                                                                                                                     buttonPressedAt = now;
                                                                                                                                                                                                                                                                                                                                                                                           longActionDone = false;
                                                                                                                                                                                                                                                                                                                                                                                               } else {
                                                                                                                                                                                                                                                                                                                                                                                                     if (!longActionDone) {
                                                                                                                                                                                                                                                                                                                                                                                                             registerShortClick(now);
                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                           if (buttonStableLevel == LOW &&
                                                                                                                                                                                                                                                                                                                                                                                                                                 !longActionDone &&
                                                                                                                                                                                                                                                                                                                                                                                                                                       now - buttonPressedAt >= LONG_PRESS_MS) {

                                                                                                                                                                                                                                                                                                                                                                                                                                           longActionDone = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                               handleLongPress();
                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                   // Одиночное нажатие подтверждается после паузы,
                                                                                                                                                                                                                                                                                                                                                                                                                                                     // чтобы отличить его от тройного нажатия.
                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (pendingClicks > 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                             now - lastClickAt >= CLICK_GAP_MS) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 processPendingClicks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                   // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   // ПОЛНОЕ СКАНИРОВАНИЕ ВСЕХ WI-FI СЕТЕЙ
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                   void startFullScan() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (scanning) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                       Serial.println("Starting full Wi-Fi scan");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                         scanError = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           lastFullScanAt = millis();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             scanStartedAt = millis();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                               WiFi.scanDelete();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 scanKind = FULL_SCAN;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   int16_t result =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       WiFi.scanNetworks(true, true, false, 120, 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (result == WIFI_SCAN_RUNNING) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             scanning = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               } else if (result >= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   scanning = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       handleScanResults(result);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             handleScanFailure();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               void finishFullScan(int16_t found) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 char previousBSSID[18] = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (networkCount > 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         selectedIndex >= 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               selectedIndex < networkCount) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   snprintf(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         previousBSSID, sizeof(previousBSSID),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               "%s", networks[selectedIndex].bssid
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       totalFound = found;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         networkCount = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // Оставляем наиболее сильные сети.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // Если найдено больше MAX_NETWORKS, заменяем
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // самую слабую сохранённую сеть более сильной.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 for (int i = 0; i < found; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     NetworkInfo item = {};

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         String ssid = WiFi.SSID(i);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             String bssid = WiFi.BSSIDstr(i);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (ssid.length() == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       snprintf(item.ssid, sizeof(item.ssid), "<hidden>");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 snprintf(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         item.ssid, sizeof(item.ssid),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 "%s", ssid.c_str()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               snprintf(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     item.bssid, sizeof(item.bssid),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           "%s", bssid.c_str()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   item.rssi = WiFi.RSSI(i);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       item.channel = WiFi.channel(i);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           item.open =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 (WiFi.encryptionType(i) == WIFI_AUTH_OPEN);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (networkCount < MAX_NETWORKS) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           networks[networkCount++] = item;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     int weakest = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           for (int j = 1; j < networkCount; j++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (networks[j].rssi < networks[weakest].rssi) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             weakest = j;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (item.rssi > networks[weakest].rssi) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         networks[weakest] = item;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       sortNetworks();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         selectedIndex = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // Сохраняем выбор при обновлении списка,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // если выбранная точка доступа всё ещё найдена.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (previousBSSID[0] != '\0') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   for (int i = 0; i < networkCount; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (strcmp(networks[i].bssid, previousBSSID) == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 selectedIndex = i;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       scanError = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         lastFullScanAt = millis();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           Serial.printf(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               "Scan complete: found %d, displayed %d\n",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   totalFound, networkCount
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       for (int i = 0; i < networkCount; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           Serial.printf(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 "%2d. %-32s %ld dBm CH:%ld %s BSSID:%s\n",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       i + 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             networks[i].ssid,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   (long)networks[i].rssi,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         (long)networks[i].channel,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               networks[i].open ? "OPEN" : "PROTECTED",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     networks[i].bssid
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // БЫСТРОЕ ИЗМЕРЕНИЕ ВЫБРАННОЙ СЕТИ
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           void recordMissedSample() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (missedSamples < 255) missedSamples++;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // Не объявляем сеть пропавшей из-за одного
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 // неудачного измерения.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (missedSamples >= 3) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       currentRSSI = -100;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           pushHistory(currentRSSI);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           void finishTrackScan(int16_t found) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             bool matched = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (networkCount > 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     selectedIndex >= 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           selectedIndex < networkCount) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const char *targetBSSID =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     networks[selectedIndex].bssid;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         for (int i = 0; i < found; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               String foundBSSID = WiFi.BSSIDstr(i);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     // Сравниваем BSSID, чтобы не спутать
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // разные точки доступа с одинаковым именем.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (foundBSSID.equalsIgnoreCase(targetBSSID)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         currentRSSI = WiFi.RSSI(i);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 networks[selectedIndex].rssi = currentRSSI;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         missedSamples = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 pushHistory(currentRSSI);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         matched = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (!matched) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   recordMissedSample();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       nextTrackScanAt = millis() + TRACK_RETRY_DELAY_MS;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       void startTrackScan() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (scanning || networkCount <= 0) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (selectedIndex < 0 ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 selectedIndex >= networkCount) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         int channel = networks[selectedIndex].channel;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (channel < 1 || channel > 14) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               nextTrackScanAt = millis() + 500;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       scanStartedAt = millis();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         scanKind = TRACK_SCAN;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // Сканируем только канал выбранной сети.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // Это значительно быстрее полного сканирования.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               int16_t result = WiFi.scanNetworks(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   true, true, false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       CHANNEL_SCAN_MS,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           (uint8_t)channel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (result == WIFI_SCAN_RUNNING) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   scanning = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     } else if (result >= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         scanning = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             handleScanResults(result);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   handleScanFailure();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     // РЕЗУЛЬТАТЫ И ОШИБКИ СКАНИРОВАНИЯ
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     void handleScanResults(int16_t found) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       ScanKind completedKind = scanKind;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         scanning = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           scanKind = NO_SCAN;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (completedKind == FULL_SCAN) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 finishFullScan(found);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   } else if (completedKind == TRACK_SCAN) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       finishTrackScan(found);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           WiFi.scanDelete();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           void handleScanFailure() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ScanKind failedKind = scanKind;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               scanning = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 scanKind = NO_SCAN;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   WiFi.scanDelete();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (failedKind == FULL_SCAN) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         scanError = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             lastFullScanAt = millis();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Serial.println("Full scan failed");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   } else if (failedKind == TRACK_SCAN) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       recordMissedSample();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           nextTrackScanAt =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 millis() + TRACK_RETRY_DELAY_MS + 120;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     Serial.println("Channel scan failed");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // ОФОРМЛЕНИЕ СПИСКА СЕТЕЙ
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       void drawSignalBars(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         uint8_t x, uint8_t y, int32_t rssi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           int levels = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (rssi >= -50) levels = 4;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               else if (rssi >= -60) levels = 3;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 else if (rssi >= -70) levels = 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   else if (rssi >= -82) levels = 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     for (int i = 0; i < 4; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         uint8_t h = 3 + i * 2;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (i < levels) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   oled.drawBox(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           x + i * 3, y + 10 - h, 2, h
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           oled.drawFrame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   x + i * 3, y + 10 - h, 2, h
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               void drawListScreen() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 oled.setFont(u8g2_font_6x10_tf);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   oled.drawStr(2, 11, "WIFI RADAR");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     char status[12];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       snprintf(status, sizeof(status), "N:%d", totalFound);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         int sw = oled.getStrWidth(status);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           oled.drawStr(126 - sw, 11, status);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             oled.drawHLine(0, 15, 128);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (networkCount == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   oled.setFont(u8g2_font_6x10_tf);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (scanning) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             oled.drawStr(12, 32, "SCANNING WI-FI");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   oled.drawFrame(8, 40, 112, 9);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         int width = (millis() / 30) % 108;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               oled.drawBox(10, 42, width, 5);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   } else if (scanError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         oled.drawStr(20, 32, "SCAN FAILED");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               oled.setFont(u8g2_font_5x8_tf);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     oled.drawStr(15, 48, "HOLD BUTTON");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           oled.drawStr(22, 59, "TO RETRY");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     oled.drawStr(11, 32, "NO NETWORKS");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           oled.setFont(u8g2_font_5x8_tf);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 oled.drawStr(13, 49, "WAITING FOR SCAN");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // Четыре строки на экране.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // Нижняя строка используется под четвёртую сеть,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 // подсказки управления внизу больше нет.
